template <size_t I, class T, size_t N>
constexpr T& get(std::array<T, N>& arr) noexcept;
// Implementation notes: I must be a compile-time constant (e.g., via template argument deduction). The compiler performs bounds checking at compile time if possible, and the function returns a reference to the I-th element in the array. If I >= N, it results in a compile-time error due to static_assert or SFINAE in standard library implementations.
